const GEO_CACHE = (()=>{ try { return JSON.parse(localStorage.getItem("bpf_geocache")||"{}"); } catch(_) { return {}; } })();
let GEO_QUEUE = Promise.resolve();
const BKK_VIEWBOX = "100.25,14.05,101.05,13.45"; // Greater Bangkok bias box (lonW,latN,lonE,latS)
function geocode(qstr){
  const key = String(qstr||"").trim().toLowerCase();
  if(!key) return Promise.resolve(null);
  if(GEO_CACHE[key]) return Promise.resolve(GEO_CACHE[key]==="none" ? null : GEO_CACHE[key]);
  const run = () => fetch("https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=th&viewbox="+BKK_VIEWBOX+"&q="+encodeURIComponent(qstr))
    .then(r=>r.json())
    .then(d=>{ const ll = (d && d[0]) ? [parseFloat(d[0].lat), parseFloat(d[0].lon)] : null; GEO_CACHE[key] = ll || "none"; try { localStorage.setItem("bpf_geocache", JSON.stringify(GEO_CACHE)); } catch(_){} return ll; })
    .catch(()=>null);
  const p = GEO_QUEUE.then(run);
  GEO_QUEUE = p.then(()=>new Promise(r=>setTimeout(r,1100)), ()=>new Promise(r=>setTimeout(r,1100)));
  return p;
}
function geoName(p){
  let t = String((p&&p.title)||"").split(/[\u2014\u2013|]/)[0].trim();
  t = t.replace(/\b(for\s+rent\s*&\s*sale|for\s+rent|for\s+sale)\b/ig,"").trim();
  const loc = String((p&&p.location)||"").trim();
  if(t && loc) return t + ", " + loc;
  return t || loc;
}
const BKK_AREAS = ["Thonglor","Thong Lo","Ekkamai","Asoke","Asok","Phrom Phong","Prompong","Nana","Ploenchit","Phloen Chit","Chidlom","Chit Lom","Sukhumvit","Silom","Sathorn","Sathon","Surawong","Siam","Ratchathewi","Phaya Thai","Ari","Ladprao","Lat Phrao","Ratchadaphisek","Ratchada","Huai Khwang","Din Daeng","Chatuchak","On Nut","Bang Na","Udom Suk","Bearing","Phra Khanong","Bang Rak","Khlong Toei","Watthana","Wireless","Witthayu","Rama 9","Rama IX","Rama 4","Rama 3","Charoenkrung","Charoen Nakhon","Thonburi","Riverside","Bang Sue","Wongwian Yai","Phetchaburi","Pinklao","Sukhumvit 24","Sukhumvit 11","Sukhumvit 31","Sukhumvit 39"];
function _gclean(s){ return String(s||"").replace(/[\u2014\u2013|\u2022]+/g," ").replace(/\s+/g," ").trim(); }
function extractSoi(text){
  const t=_gclean(text);
  let m=t.match(/(?:soi|\u0E0B\u0E2D\u0E22)\s*([0-9]{1,3}(?:\/[0-9]{1,3})?)/i);
  if(m) return "Soi "+m[1];
  m=t.match(/\b(sukhumvit|thonglor|thong\s?lo|ekkamai|silom|sathorn|sathon|ladprao|lat\s?phrao|ratchadaphisek|ratchada|phaholyothin|phahonyothin|charoenkrung|narathiwat|ratchadamri|petchaburi|phetchaburi)\s*(\d{1,3})\b/i);
  if(m) return _gclean(m[1]).replace(/\b\w/g,c=>c.toUpperCase())+" "+m[2];
  return "";
}
function extractStation(text){
  const t=_gclean(text);
  let m=t.match(/\b([A-Za-z\u0E00-\u0E7F][A-Za-z\u0E00-\u0E7F'.]{1,18})\s+(BTS|MRT|ARL)\b/i);
  if(m && !/^(near|the|min|walk|to|from|bangkok|thailand|condo|apartment|in|at|soi)$/i.test(m[1])) return m[2].toUpperCase()+" "+m[1].trim();
  m=t.match(/\b(BTS|MRT|ARL)\s+([A-Za-z\u0E00-\u0E7F][A-Za-z\u0E00-\u0E7F'.]{1,18})/i);
  if(m && !/^(station|near|min|walk|to|the)$/i.test(m[2])) return m[1].toUpperCase()+" "+m[2].trim();
  return "";
}
function extractArea(text){
  const t=_gclean(text);
  for(const a of BKK_AREAS){ const re=new RegExp("\\b"+a.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+"\\b","i"); if(re.test(t)) return a; }
  return "";
}
function geoCandidates(p){
  let title=String((p&&p.title)||"").split(/[\u2014\u2013|]/)[0].replace(/\b(for\s+rent\s*&\s*sale|for\s+rent|for\s+sale)\b/ig,"").replace(/\s+/g," ").trim();
  const loc=String((p&&p.location)||"").trim();
  const blob=[p&&p.title,p&&p.location,p&&p.bts,p&&p.facilities].filter(Boolean).join("  ");
  const out=[];
  // Layer 1 — exact building name (+ area), and a shortened name for partial/typo tolerance
  if(title){ out.push(loc?(title+", "+loc):(title+", Bangkok")); out.push(title+", Bangkok"); const w=title.split(/\s+/); if(w.length>2) out.push(w.slice(0,2).join(" ")+", "+(loc||"Bangkok")); }
  // Layer 2 — Soi / sub-street
  const soi=extractSoi(blob); if(soi) out.push(soi+(loc?(", "+loc):"")+", Bangkok");
  // Layer 3 — nearest BTS/MRT station (from the bts field first, then any text)
  let btsRaw=String((p&&p.bts)||"").replace(/^\s*(near|close to|next to|\u0E43\u0E01\u0E25\u0E49)\s+/i,"").split(/[\u2014\u2013(]|\d/)[0].replace(/\s+/g," ").replace(/[\s\-\u2013\u2014,.:|]+$/,"").trim();
  if(btsRaw && btsRaw.length>=3) out.push(btsRaw+(/(bts|mrt|arl|station|\u0E2A\u0E16\u0E32\u0E19\u0E35)/i.test(btsRaw)?"":" BTS")+", Bangkok");
  const st=extractStation(blob); if(st) out.push(st+", Bangkok");
  // Layer 4 — district / area centre
  const area=extractArea(blob); if(area) out.push(area+", Bangkok");
  if(loc) out.push(/thailand/i.test(loc)?loc:(loc+", Thailand"));
  const seen={},res=[]; out.forEach(q=>{ const k=String(q).toLowerCase().trim(); if(q&&!seen[k]){seen[k]=1;res.push(q);} }); return res;
}
async function geocodeSmart(p){
  const cands=geoCandidates(p);
  for(const q of cands){ try{ const ll=await geocode(q); if(ll) return ll; }catch(_){} }
  return null;
}

function MapView({ items, onOpen, lang }){
  const mapRef = useRef(null);
  const objRef = useRef(null);
  const [ready, setReady] = useState(false);
  const [show, setShow] = useState({ transit:true, mall:false, hospital:false, school:false, park:false });
  const P = POI_LABELS[lang] || POI_LABELS.en;
  const showRef = useRef(show);
  showRef.current = show;

  const popupHtml = (p) => {
    const img = p.img || (Array.isArray(p.imgs) && p.imgs[0]) || "";
    const bits = [];
    if(p.beds!=null && p.beds!=="") bits.push(escapeHtml(p.beds)+" bd");
    if(p.baths!=null && p.baths!=="") bits.push(escapeHtml(p.baths)+" ba");
    if(p.sqm) bits.push(escapeHtml(p.sqm)+" m\u00B2");
    return (img ? "<img src='"+escapeHtml(img)+"' style='width:100%;height:118px;object-fit:cover;border-radius:8px;margin-bottom:8px'/>" : "")
      + (p.ref ? "<div style='font:700 10px Outfit,sans-serif;letter-spacing:.08em;color:#9B6B2A;text-transform:uppercase'>"+escapeHtml(p.ref)+"</div>" : "")
      + "<div style='font:700 16px \"Cormorant Garamond\",serif;color:#1C1410;line-height:1.2;margin:2px 0 3px'>"+escapeHtml(p.title||"")+"</div>"
      + "<div style='font:700 14px \"Cormorant Garamond\",serif;color:#B8893A;margin-bottom:4px'>"+escapeHtml(priceDisplay(p))+"</div>"
      + (bits.length ? "<div style='font:500 11px Outfit,sans-serif;color:#6B5E52;margin-bottom:9px'>"+bits.join(" \u00B7 ")+"</div>" : "")
      + "<button class='bpf-open' type='button' style='width:100%;border:none;cursor:pointer;background:linear-gradient(135deg,#C9A96E,#9B6B2A);color:#fff;border-radius:8px;padding:7px 8px;font:700 12px Outfit,sans-serif'>"+escapeHtml(P.view)+"</button>";
  };

  useEffect(()=>{
    let cancelled = false;
    const ensureCss = (id, href) => { if(!document.getElementById(id)){ const l=document.createElement("link"); l.id=id; l.rel="stylesheet"; l.href=href; document.head.appendChild(l); } };
    const ensureJs = (id, src) => new Promise((res)=>{
      const done = () => res();
      let s = document.getElementById(id);
      if(s){ if(window.L && (id!=="leaflet-cluster-js" || window.L.markerClusterGroup)) return done(); s.addEventListener("load", done); s.addEventListener("error", done); return; }
      s = document.createElement("script"); s.id=id; s.src=src; s.onload=done; s.onerror=done; document.head.appendChild(s);
    });
    const ensureStyle = (id, css) => { if(!document.getElementById(id)){ const st=document.createElement("style"); st.id=id; st.textContent=css; document.head.appendChild(st); } };
    (async ()=>{
      ensureCss("leaflet-css","https://unpkg.com/leaflet@1.9.4/dist/leaflet.css");
      ensureCss("leaflet-cluster-css","https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.css");
      ensureCss("leaflet-cluster-default-css","https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.Default.css");
      await ensureJs("leaflet-js","https://unpkg.com/leaflet@1.9.4/dist/leaflet.js");
      await ensureJs("leaflet-cluster-js","https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js");
      const L = window.L;
      if(cancelled || !L || !mapRef.current || objRef.current) return;
      ensureStyle("bpf-map-style", BPF_MAP_CSS);
      const map = L.map(mapRef.current, { scrollWheelZoom:true }).setView([13.7563,100.5018], 11);
      L.tileLayer("https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png", { subdomains:"abcd", maxZoom:20, attribution:"\u00A9 OpenStreetMap \u00A9 CARTO" }).addTo(map);
      const listingLayer = (typeof L.markerClusterGroup === "function") ? L.markerClusterGroup({ maxClusterRadius:58, showCoverageOnHover:false, spiderfyOnMaxZoom:false, zoomToBoundsOnClick:false, spiderfyDistanceMultiplier:2, iconCreateFunction:function(c){ const n=c.getChildCount(); const sz=n<6?40:n<20?48:56; return L.divIcon({ className:"", iconSize:[sz,sz], html:"<div class='bpf-cl' style='width:"+sz+"px;height:"+sz+"px'>"+n+"</div>" }); } }) : L.layerGroup();
      map.addLayer(listingLayer);
      if(typeof L.markerClusterGroup === "function"){
        listingLayer.on("clusterclick", function(a){
          const cl=a.layer, ms=cl.getAllChildMarkers(); let same=false;
          if(ms.length>1){ const z=ms[0].getLatLng(); same=ms.every(m=>{ const l=m.getLatLng(); return Math.abs(l.lat-z.lat)<1.5e-4 && Math.abs(l.lng-z.lng)<1.5e-4; }); }
          if(same){ cl.spiderfy(); } else { try{ cl.zoomToBounds({ padding:[40,40] }); }catch(_){ cl.spiderfy(); } }
        });
      }
      const poiLayers = {};
      POI_ORDER.forEach(cat=>{
        const lg = L.layerGroup();
        (BKK_POI[cat].items||[]).forEach(([name,lat,lng])=>{
          const mk = L.marker([lat,lng], { icon: poiDiv(L, cat) });
          mk.bindPopup("<div style='font:600 13px Outfit,sans-serif;color:#1C1410'>"+escapeHtml(name)+"</div><div style='font:600 11px Outfit,sans-serif;color:"+BKK_POI[cat].color+"'>"+escapeHtml(P[cat])+"</div>");
          lg.addLayer(mk);
        });
        poiLayers[cat] = lg;
        if(showRef.current[cat]) map.addLayer(lg);
      });
      objRef.current = { map, listingLayer, poiLayers };
      setReady(true);
      setTimeout(()=>{ try { map.invalidateSize(); } catch(_){} }, 250);
    })();
    return ()=>{ cancelled = true; if(objRef.current && objRef.current.map){ try { objRef.current.map.remove(); } catch(_){} objRef.current = null; } };
  }, []);

  useEffect(()=>{
    let cancelled = false;
    const o = objRef.current, L = window.L;
    if(!o || !L) return;
    o.listingLayer.clearLayers();
    const pts = [];
    const addMarker = (p, ll) => {
      if(cancelled || !objRef.current) return;
      const mk = L.marker(ll, { icon: pillDiv(L, p, false) });
      mk.bindPopup(popupHtml(p), { minWidth:200, maxWidth:240 });
      mk.on("popupopen", (e)=>{ try { mk.setIcon(pillDiv(L,p,true)); const b = e.popup._contentNode.querySelector(".bpf-open"); if(b) b.onclick = ()=>onOpen(p); } catch(_){} });
      mk.on("popupclose", ()=>{ try { mk.setIcon(pillDiv(L,p,false)); } catch(_){} });
      o.listingLayer.addLayer(mk);
    };
    items.forEach(p=>{ const ll = parseLatLng(p.maplink); if(ll){ pts.push(ll); addMarker(p, ll); } });
    if(pts.length && ready){ try { o.map.fitBounds(pts, { padding:[45,45], maxZoom:15 }); } catch(_){} }
    const missing = items.filter(p=>!parseLatLng(p.maplink) && p.location).slice(0,12);
    missing.forEach(p=>{ geocodeSmart(p).then(ll=>{ if(ll) addMarker(p, ll); }); });
    return ()=>{ cancelled = true; };
  }, [items, ready, lang]);

  const toggle = (cat) => {
    setShow(prev=>{
      const nv = { ...prev, [cat]: !prev[cat] };
      const o = objRef.current;
      if(o && window.L){ if(nv[cat]) o.map.addLayer(o.poiLayers[cat]); else o.map.removeLayer(o.poiLayers[cat]); }
      return nv;
    });
  };

  const counted = items.filter(p=>parseLatLng(p.maplink)).length;
  return (
    <div style={{ position:"relative", borderRadius:18, overflow:"hidden", border:"1px solid #EFE8DF", boxShadow:"0 4px 20px rgba(0,0,0,0.06)" }}>
      <div ref={mapRef} style={{ height:"clamp(440px,70vh,720px)", width:"100%", background:"#F5F3EF" }} />
      <div style={{ position:"absolute", top:12, right:12, zIndex:600, width:230, maxWidth:"calc(100% - 24px)", background:"rgba(255,255,255,0.82)", backdropFilter:"blur(14px)", WebkitBackdropFilter:"blur(14px)", border:"1px solid rgba(201,169,110,0.28)", borderRadius:16, padding:"12px 12px 10px", boxShadow:"0 10px 30px rgba(28,20,4,0.14)" }}>
        <div style={{ fontSize:10, fontWeight:800, letterSpacing:"0.14em", textTransform:"uppercase", color:"#9B6B2A", marginBottom:9, paddingLeft:2 }}>{P.title}</div>
        <div style={{ display:"flex", flexDirection:"column", gap:5 }}>
          {POI_ORDER.map(cat=>{
            const on = !!show[cat]; const c = BKK_POI[cat].color;
            return (
              <button key={cat} type="button" onClick={()=>toggle(cat)} style={{ display:"flex", alignItems:"center", gap:9, width:"100%", border:"1px solid "+(on?c+"66":"#EFE8DF"), background:on?c+"14":"transparent", borderRadius:11, padding:"7px 9px", cursor:"pointer", textAlign:"left", transition:"all .15s", fontFamily:"'Outfit',sans-serif" }}>
                <span style={{ width:24, height:24, borderRadius:7, flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center", background:on?c+"24":"#F1ECE5", color:on?c:"#B8AEA2", transition:"all .15s" }} dangerouslySetInnerHTML={{ __html: POI_ICONS[cat]||"" }} />
                <span style={{ flex:1, minWidth:0, fontSize:12, fontWeight:600, color:on?"#1C1410":"#A89580", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{P[cat]}</span>
                <span style={{ fontSize:10, fontWeight:700, color:on?c:"#C9BEB0", flexShrink:0 }}>{(BKK_POI[cat].items||[]).length}</span>
                <span style={{ width:30, height:17, borderRadius:9, flexShrink:0, position:"relative", background:on?c:"#DDD4C8", transition:"background .18s" }}>
                  <span style={{ position:"absolute", top:2, left:on?15:2, width:13, height:13, borderRadius:"50%", background:"#fff", boxShadow:"0 1px 3px rgba(0,0,0,0.25)", transition:"left .18s" }} />
                </span>
              </button>
            );
          })}
        </div>
      </div>
      <div style={{ position:"absolute", bottom:14, left:14, zIndex:600, background:"rgba(28,16,8,0.92)", color:"#F5E9D0", borderRadius:20, padding:"6px 15px", fontSize:12.5, fontWeight:700, display:"flex", alignItems:"center", gap:7 }}>
        <span style={{ width:11, height:11, borderRadius:"50%", background:"linear-gradient(135deg,#C9A96E,#9B6B2A)", display:"inline-block", border:"2px solid #F5E9D0" }} />
        {counted} {P.listings}
      </div>
    </div>
  );
}

function PublicSite({ props, isAdmin, cityPhotos={}, onEditProp, onDelProp, onGoAdmin, agentContacts={} }) {
  const [city, setCity]       = useState("Bangkok");
  const [area, setArea]       = useState("All Areas");
  const [line, setLine]       = useState("All Lines");
  const [station, setStation] = useState("All Stations");
  const [types, setTypes]     = useState([]);
  const [beds, setBeds]       = useState([]);
  const [status, setStatus]   = useState("All");
  const [priceMin, setPriceMin] = useState("");
  const [priceMax, setPriceMax] = useState("");
  const [sizeMin, setSizeMin]   = useState("");
  const [sizeMax, setSizeMax]   = useState("");
  const [q, setQ]             = useState("");
  const [showFilters, setShowFilters] = useState(false);
  const [view, setView] = useState("list");
  const toggleIn = (setter) => (v) => setter(prev => prev.includes(v) ? prev.filter(x=>x!==v) : [...prev, v]);
  const clearFilters = () => { setTypes([]); setBeds([]); setStatus("All"); setPriceMin(""); setPriceMax(""); setSizeMin(""); setSizeMax(""); setLine("All Lines"); setStation("All Stations"); setArea("All Areas"); setQ(""); };
  const fLabel = { fontSize:11, fontWeight:700, color:"#7B6A5A", letterSpacing:"0.06em", textTransform:"uppercase", marginBottom:8, display:"block" };
  const fChip = (on) => ({ padding:"6px 13px", borderRadius:20, border:"1.5px solid", borderColor: on?"#C9A96E":"#E5DDD3", background: on?"#C9A96E":"transparent", color: on?"#fff":"#7B6A5A", fontSize:12, fontWeight:600, cursor:"pointer", transition:"all 0.15s" });
  const fNum = { width:"100%", padding:"9px 10px", borderRadius:9, border:"1px solid #E5DDD3", fontSize:13, background:"#FDFAF6", color:"#1C1410" };
  const [heroOn, setHeroOn]   = useState(false);
  const [contact, setContact] = useState({ name:"", email:"", phone:"", budget:"", location:"", beds:"Any", movein:"", msg:"" });
  const [sent, setSent]       = useState(false);

  const [selectedId, setSelectedId] = useState(null);
  const [openGuide, setOpenGuide] = useState(null);
  const [lang, setLang] = useState(()=>{ try { return localStorage.getItem("bpf_lang") || "en"; } catch(_) { return "en"; } });
  useEffect(()=>{ try { localStorage.setItem("bpf_lang", lang); } catch(_) {} }, [lang]);
  const t = UI[lang] || UI.en;
  const guides = GUIDES_I18N[lang] || GUIDES_I18N.en;

  useEffect(() => { const tm = setTimeout(() => setHeroOn(true), 80); return () => clearTimeout(tm); }, []);
  useEffect(() => {
    const readParam = () => { try { setSelectedId(new URLSearchParams(window.location.search).get("p")); } catch(_) {} };
    readParam();
    window.addEventListener("popstate", readParam);
    return () => window.removeEventListener("popstate", readParam);
  }, []);
  const openDetail = (p) => { setSelectedId(String(p.id)); try { window.history.pushState({}, "", "?p=" + p.id); } catch(_) {} };
  const closeDetail = () => { setSelectedId(null); try { window.history.pushState({}, "", window.location.pathname); } catch(_) {} };

  const _pmin = parseInt(String(priceMin).replace(/[^0-9]/g,""),10) || 0;
  const _pmax = parseInt(String(priceMax).replace(/[^0-9]/g,""),10) || Infinity;
  const _smin = parseInt(String(sizeMin).replace(/[^0-9]/g,""),10) || 0;
  const _smax = parseInt(String(sizeMax).replace(/[^0-9]/g,""),10) || Infinity;
  const bedKey = (b) => { const n = parseInt(b,10); if (!n || n<=0) return "Studio"; if (n>=3) return "3+"; return String(n); };
  const matchStatus = (ps) => {
    if (status === "All") return true;
    if (status === "For Rent & Sale") return ps === "For Rent & Sale";
    return ps === status || ps === "For Rent & Sale";
  };
  const priceForFilter = (p) => (status === "For Sale" && (p.status||"") === "For Rent & Sale") ? parsePrice(p.pricesale || p.price) : parsePrice(p.price);
  const shown = props.filter(p => {
    if (p.active === false) return false;
    if (p.approved === "0") return false;
    if (types.length && !types.includes(p.type)) return false;
    if (!matchStatus(p.status || "")) return false;
    if (!p.location.toLowerCase().includes(city.toLowerCase())) return false;
    if (area !== "All Areas") {
      const keys = area.split("/").map(a => a.trim().toLowerCase());
      const loc = (p.location + " " + (p.bts||"")).toLowerCase();
      if (!keys.some(k => loc.includes(k))) return false;
    }
    if (line !== "All Lines") {
      const stations = TRANSIT_LINES[line] || [];
      const bts = (p.bts||"").toLowerCase();
      if (!stations.some(s => bts.includes(s.toLowerCase()))) return false;
    }
    if (station !== "All Stations") {
      if (!(p.bts||"").toLowerCase().includes(station.toLowerCase())) return false;
    }
    if (beds.length && !beds.includes(bedKey(p.beds))) return false;
    const pr = priceForFilter(p);
    if (pr < _pmin || pr > _pmax) return false;
    const sz = parseInt(p.sqm,10) || 0;
    if (sz < _smin || sz > _smax) return false;
    if (q && !matchSearch(p, q)) return false;
    return true;
  });
  const totalActive = props.filter(p => p.active!==false && p.approved!=="0").length;
  const activeChips = [];
  types.forEach(tp => activeChips.push({ k:"type:"+tp, label:tp, on:()=>setTypes(prev=>prev.filter(x=>x!==tp)) }));
  beds.forEach(b => activeChips.push({ k:"bed:"+b, label:(b==="Studio"?t.flt.studio:b)+" "+t.fBeds, on:()=>setBeds(prev=>prev.filter(x=>x!==b)) }));
  if (status !== "All") activeChips.push({ k:"status", label:(status==="For Rent"?t.sRent:status==="For Sale"?t.sSale:t.flt.statusBoth), on:()=>setStatus("All") });
  if (area !== "All Areas") activeChips.push({ k:"area", label:area, on:()=>setArea("All Areas") });
  if (line !== "All Lines") activeChips.push({ k:"line", label:line, on:()=>{ setLine("All Lines"); setStation("All Stations"); } });
  if (station !== "All Stations") activeChips.push({ k:"station", label:station, on:()=>setStation("All Stations") });
  if (priceMin || priceMax) activeChips.push({ k:"price", label:t.flt.price+": "+(priceMin||"0")+"\u2013"+(priceMax||"\u221E"), on:()=>{ setPriceMin(""); setPriceMax(""); } });
  if (sizeMin || sizeMax) activeChips.push({ k:"size", label:t.flt.size+": "+(sizeMin||"0")+"\u2013"+(sizeMax||"\u221E"), on:()=>{ setSizeMin(""); setSizeMax(""); } });
  if (q) activeChips.push({ k:"q", label:"\u201C"+q+"\u201D", on:()=>setQ("") });
  const areaOptions = CITY_AREAS[city] ? ["All Areas", ...CITY_AREAS[city]] : null;
  const lineOptions = ["All Lines", ...Object.keys(TRANSIT_LINES)];

  const fadeUp = (d=0) => ({ opacity:heroOn?1:0, transform:heroOn?"translateY(0)":"translateY(24px)", transition:`opacity 0.75s ease ${d}s, transform 0.75s ease ${d}s` });

  return (
    <div style={{ fontFamily:"'Outfit',sans-serif", background:"#FDFAF6", color:"#1C1410", minHeight:"100vh" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;0,700;1,400;1,600&family=Outfit:wght@300;400;500;600;700&display=swap');
        *{box-sizing:border-box;margin:0;padding:0}
        html{scroll-behavior:smooth}
        ::-webkit-scrollbar{width:5px}::-webkit-scrollbar-thumb{background:#C9A96E;border-radius:4px}
        input,select,textarea,button{font-family:'Outfit',sans-serif}
        @keyframes fadeUp{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:translateY(0)}}
        @keyframes floatBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
        .bpf-mbar{display:flex}.bpf-mbar-sp{display:none}
        @media(max-width:820px){.bpf-navlinks{display:none}}
        @media(max-width:820px){
          .bpf-fbtn{display:inline-flex !important}
          .bpf-filterwrap{position:fixed;inset:0;z-index:700;background:rgba(15,10,4,0.55);display:none}
          .bpf-filterwrap[data-open="true"]{display:block}
          .bpf-filterpanel{position:absolute;top:0;right:0;bottom:0;width:min(90%,370px);max-width:90%;overflow-y:auto;border-radius:0 !important;margin:0 !important;border:none !important}
          .bpf-fclose{display:flex !important}
          .bpf-fapply{display:inline-flex !important}
        }
        @media(min-width:900px){.bpf-mbar{display:none}}
        @media(max-width:899px){.bpf-mbar-sp{display:block}}
      `}</style>

      {/* NAV */}
      <nav style={{ position:"fixed", top:0, left:0, right:0, zIndex:200, background:"rgba(253,250,246,0.98)", backdropFilter:"blur(18px)", borderBottom:"1px solid rgba(201,169,110,0.25)", boxShadow:"0 2px 20px rgba(0,0,0,0.06)", padding:"0 clamp(16px,4vw,48px)" }}>
        <div style={{ maxWidth:1200, margin:"0 auto", display:"flex", alignItems:"center", justifyContent:"space-between", height:64 }}>
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                        <img src={LOGO_IMG} alt="Bangkok Property Finder" style={{ height:52, width:"auto", objectFit:"contain", flexShrink:0 }}/>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:14 }}>
            <div className="bpf-navlinks" style={{ display:"flex", alignItems:"center", gap:20 }}>
              {[["buy",t.nav[0]],["rent",t.nav[1]],["services",t.nav[2]],["contact",t.nav[3]]].map(([href,l])=>(
                <a key={href} href={`#${href}`} style={{ color:"#6B5E52", fontSize:13, fontWeight:500, textDecoration:"none", letterSpacing:"0.04em" }}
                  onMouseEnter={e=>e.target.style.color="#C9A96E"} onMouseLeave={e=>e.target.style.color="#6B5E52"}>{l}</a>
              ))}
              <a href={OWNER.igUrl} target="_blank" rel="noreferrer" style={{ color:"#6B5E52", fontSize:12, fontWeight:500, textDecoration:"none" }}
                onMouseEnter={e=>e.target.style.color="#E1306C"} onMouseLeave={e=>e.target.style.color="#6B5E52"}>
                <span style={{ display:"inline-flex", alignItems:"center", gap:5 }}><Icon n="instagram" s={14} c="#6B5E52"/>@{OWNER.ig}</span>
              </a>
            </div>
            <div style={{ display:"flex", gap:2, background:"#F3EEE8", borderRadius:20, padding:3 }}>
              {[["en","EN"],["th","ไทย"],["zh","中文"]].map(([code,lbl])=>(
                <button key={code} onClick={()=>setLang(code)} style={{ border:"none", cursor:"pointer", borderRadius:16, padding:"5px 9px", fontSize:11, fontWeight:700, background: lang===code?"#1C1410":"transparent", color: lang===code?"#C9A96E":"#7B6A5A", whiteSpace:"nowrap" }}>{lbl}</button>
              ))}
            </div>
            <button onClick={onGoAdmin} style={{ background:"linear-gradient(135deg,#C9A96E,#9B6B2A)", color:"#fff", border:"none", padding:"7px 16px", borderRadius:20, fontSize:12, fontWeight:600, cursor:"pointer", letterSpacing:"0.03em", whiteSpace:"nowrap" }}>{t.admin}</button>
          </div>
        </div>
      </nav>

      {/* HERO */}
      <section style={{ position:"relative", minHeight:"100vh", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", overflow:"hidden", paddingTop:80, paddingBottom:160 }}>
        <div style={{ position:"absolute", inset:0, backgroundImage:"url('https://images.unsplash.com/photo-1616594039964-ae9021a400a0?w=1900&q=85')", backgroundSize:"cover", backgroundPosition:"center" }}/>
        <div style={{ position:"absolute", inset:0, background:"linear-gradient(160deg,rgba(28,16,8,0.85) 0%,rgba(40,24,12,0.55) 50%,rgba(20,12,6,0.9) 100%)" }}/>
        <div style={{ position:"absolute", top:"13%", right:"7%", width:200, height:200, borderRadius:"50%", border:"1px solid rgba(201,169,110,0.18)", animation:"floatBob 5s ease-in-out infinite", pointerEvents:"none" }}/>

        <div style={{ position:"relative", zIndex:2, textAlign:"center", padding:"0 20px", maxWidth:900, width:"100%" }}>
          <div style={{ ...fadeUp(0.1), display:"inline-flex", alignItems:"center", gap:8, background:"rgba(245,158,11,0.12)", border:"1px solid rgba(245,158,11,0.35)", borderRadius:24, padding:"6px 16px", marginBottom:22 }}>
            <span>🇹🇭</span>
            <span style={{ color:"#F59E0B", fontSize:11, fontWeight:700, letterSpacing:"0.12em", textTransform:"uppercase" }}>{t.heroBadge}</span>
          </div>
          <div style={fadeUp(0.2)}>
            <h1 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:"clamp(40px,6.5vw,80px)", fontWeight:700, color:"#F5E9D0", lineHeight:1.08, marginBottom:18, textShadow:"0 4px 30px rgba(0,0,0,0.5)" }}>
              {t.heroH1a}<br/><em style={{ color:"#F59E0B" }}>{t.heroH1b}</em>
            </h1>
            <p style={{ color:"#B0A090", fontSize:"clamp(14px,1.8vw,17px)", lineHeight:1.8, maxWidth:500, margin:"0 auto 36px" }}>
              {t.heroSub1}<strong style={{ color:"#C9A96E" }}>Annie</strong>{t.heroSub2}
            </p>
          </div>
          <div style={fadeUp(0.35)}>
            <div style={{ background:"rgba(253,250,246,0.97)", borderRadius:18, padding:"17px", boxShadow:"0 28px 70px rgba(0,0,0,0.38)", display:"flex", gap:9, alignItems:"center", flexWrap:"wrap" }}>
              <div style={{ display:"flex", gap:4, background:"#F3EEE8", padding:4, borderRadius:10 }}>
                {["All","For Sale","For Rent"].map(s=>(
                  <button key={s} onClick={()=>setStatus(s)} style={{ padding:"6px 11px", borderRadius:7, border:"none", background:status===s?"#1C1410":"transparent", color:status===s?"#C9A96E":"#7B6A5A", fontSize:11, fontWeight:700, cursor:"pointer", transition:"all 0.15s", whiteSpace:"nowrap" }}>
                    {s==="All"?t.sBuyRent:(s==="For Sale"?t.sSale:t.sRent)}
                  </button>
                ))}
              </div>
              <select value={city} onChange={e=>{ setCity(e.target.value); setArea("All Areas"); setLine("All Lines"); setStation("All Stations"); }} style={S.inp({ minWidth:120, flex:1, cursor:"pointer", padding:"9px 10px" })}>
                {ALL_CITIES.map(c=><option key={c}>{c}</option>)}
              </select>
              {areaOptions && (
                <select value={area} onChange={e=>{ setArea(e.target.value); setStation("All Stations"); }} style={S.inp({ minWidth:130, flex:1, cursor:"pointer", padding:"9px 10px" })}>
                  {areaOptions.map(a=><option key={a}>{a}</option>)}
                </select>
              )}
              {city==="Bangkok" && (
                <>
                <select value={line} onChange={e=>{ setLine(e.target.value); setStation("All Stations"); }} style={S.inp({ minWidth:150, flex:1, cursor:"pointer", padding:"9px 10px" })}>
                  {lineOptions.map(l=><option key={l}>{l}</option>)}
                </select>
                <select value={station} onChange={e=>setStation(e.target.value)} style={S.inp({ minWidth:150, flex:1, cursor:"pointer", padding:"9px 10px" })}>
                  <option>All Stations</option>
                  {AREA_STATIONS[area]
                    ? AREA_STATIONS[area].map(st=><option key={st}>{st}</option>)
                    : line !== "All Lines"
                      ? (TRANSIT_LINES[line]||[]).map(st=><option key={st}>{st}</option>)
                      : Object.entries(TRANSIT_LINES).map(([ln,sts])=>(
                          <optgroup key={ln} label={ln}>
                            {sts.map(st=><option key={ln+st} value={st}>{st}</option>)}
                          </optgroup>
                        ))}
                </select>
                </>
              )}
              <select value={types.length===1?types[0]:"All"} onChange={e=>{ const v=e.target.value; setTypes(v==="All"?[]:[v]); }} style={S.inp({ minWidth:110, cursor:"pointer", padding:"9px 10px" })}>
                {ALL_TYPES.map(tp=><option key={tp} value={tp}>{tp}</option>)}
              </select>
              <input value={q} onChange={e=>setQ(e.target.value)} placeholder={t.searchPh} style={S.inp({ flex:2, minWidth:130 })} onFocus={onFG} onBlur={onBG}/>
              <button onClick={()=>document.getElementById("buy")?.scrollIntoView({behavior:"smooth"})} style={{...S.gold, whiteSpace:"nowrap"}}>{t.searchBtn}</button>
            </div>
          </div>
          <div style={{ ...fadeUp(0.45), display:"flex", gap:12, justifyContent:"center", flexWrap:"wrap", marginTop:24 }}>
            <button onClick={()=>document.getElementById("buy")?.scrollIntoView({behavior:"smooth"})} style={{ background:"linear-gradient(135deg,#C9A96E,#9B6B2A)", color:"#fff", border:"none", padding:"13px 28px", borderRadius:30, fontSize:14, fontWeight:700, cursor:"pointer", letterSpacing:"0.02em", boxShadow:"0 10px 30px rgba(201,169,110,0.35)" }}>{t.ctaFind}</button>
            <button onClick={()=>document.getElementById("contact")?.scrollIntoView({behavior:"smooth"})} style={{ background:"rgba(253,250,246,0.12)", color:"#F5E9D0", border:"1px solid rgba(245,233,208,0.4)", padding:"13px 28px", borderRadius:30, fontSize:14, fontWeight:700, cursor:"pointer", letterSpacing:"0.02em", backdropFilter:"blur(4px)" }}>{t.ctaContact}</button>
          </div>
        </div>

        <div style={{ position:"absolute", bottom:0, left:0, right:0, background:"rgba(12,7,2,0.88)", backdropFilter:"blur(12px)", borderTop:"1px solid rgba(201,169,110,0.15)", padding:"18px clamp(20px,5vw,60px)", opacity:heroOn?1:0, transition:"opacity 1.2s 0.7s" }}>
          <div style={{ maxWidth:1200, margin:"0 auto", display:"flex", justifyContent:"space-around", flexWrap:"wrap", gap:16 }}>
            {[{i:"pin",t:t.trust[0]},{i:"search",t:t.trust[1]},{i:"key",t:t.trust[2]},{i:"check",t:t.trust[3]}].map((x)=>(
              <div key={x.t} style={{ textAlign:"center", display:"flex", flexDirection:"column", alignItems:"center", gap:7 }}>
                <Icon n={x.i} s={24} c="#F59E0B"/>
                <div style={{ color:"#C9A96E", fontSize:11, letterSpacing:"0.07em", textTransform:"uppercase", fontWeight:600 }}>{x.t}</div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* LISTINGS */}
      <section id="buy" style={{ padding:"72px clamp(20px,5vw,60px)", maxWidth:1200, margin:"0 auto" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-end", marginBottom:28, flexWrap:"wrap", gap:14 }}>
          <div>
            <div style={{ color:"#F59E0B", fontSize:10, fontWeight:700, letterSpacing:"0.15em", textTransform:"uppercase", marginBottom:8 }}>{t.live}</div>
            <h2 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:"clamp(26px,4vw,44px)", fontWeight:700, color:"#1C1410" }}>{t.propsIn} {city}</h2>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:12, flexWrap:"wrap" }}>
            <div style={{ fontSize:13, color:"#7B6A5A", fontWeight:600 }}>{t.flt.showing} <strong style={{ color:"#1C1410" }}>{shown.length}</strong> {t.flt.of} {totalActive}</div>
            <div style={{ display:"flex", gap:3, background:"#F3EEE8", padding:3, borderRadius:10 }}>
              {[["list",t.flt.listView,"layers"],["map",t.flt.mapView,"pin"]].map(([v,lbl,ic])=>(
                <button key={v} onClick={()=>setView(v)} style={{ display:"inline-flex", alignItems:"center", gap:6, border:"none", cursor:"pointer", borderRadius:8, padding:"7px 13px", fontSize:12.5, fontWeight:700, background: view===v?"#1C1410":"transparent", color: view===v?"#C9A96E":"#7B6A5A", transition:"all 0.15s", whiteSpace:"nowrap" }}><Icon n={ic} s={14} c={view===v?"#C9A96E":"#7B6A5A"}/>{lbl}</button>
              ))}
            </div>
            <button className="bpf-fbtn" onClick={()=>setShowFilters(true)} style={{ display:"none", alignItems:"center", gap:7, background:"#1C1410", color:"#C9A96E", border:"none", borderRadius:12, padding:"9px 16px", fontSize:13, fontWeight:700, cursor:"pointer" }}><Icon n="search" s={15} c="#C9A96E"/>{t.flt.filters}</button>
          </div>
        </div>

        <div className="bpf-filterwrap" data-open={showFilters} onClick={()=>setShowFilters(false)}>
          <div className="bpf-filterpanel" onClick={e=>e.stopPropagation()} style={{ background:"#fff", border:"1px solid #EFE8DF", borderRadius:18, padding:"20px 22px", marginBottom:22, boxShadow:"0 4px 20px rgba(0,0,0,0.05)" }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16 }}>
              <div style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:20, fontWeight:700, color:"#1C1410", display:"flex", alignItems:"center", gap:8 }}><Icon n="search" s={18} c="#C9A96E"/>{t.flt.filters}</div>
              <button onClick={()=>setShowFilters(false)} className="bpf-fclose" style={{ display:"none", background:"#F3EEE8", border:"none", borderRadius:8, width:30, height:30, fontSize:18, cursor:"pointer", color:"#6B5E52" }}>×</button>
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))", gap:18 }}>
              <div>
                <label style={fLabel}>{t.flt.type}</label>
                <div style={{ display:"flex", flexWrap:"wrap", gap:7 }}>
                  {["Condo","House","Apartment","Villa","Townhouse"].map(tp=>{ const on=types.includes(tp); return (
                    <button key={tp} onClick={()=>setTypes(prev=>prev.includes(tp)?prev.filter(x=>x!==tp):[...prev,tp])} style={fChip(on)}>{tp}</button>
                  );})}
                </div>
              </div>
              <div>
                <label style={fLabel}>{t.flt.status}</label>
                <div style={{ display:"flex", flexWrap:"wrap", gap:7 }}>
                  {[["All",t.flt.all],["For Rent",t.sRent],["For Sale",t.sSale],["For Rent & Sale",t.flt.statusBoth]].map(([val,lbl])=>(
                    <button key={val} onClick={()=>setStatus(val)} style={fChip(status===val)}>{lbl}</button>
                  ))}
                </div>
              </div>
              <div>
                <label style={fLabel}>{t.fBeds}</label>
                <div style={{ display:"flex", flexWrap:"wrap", gap:7 }}>
                  {["Studio","1","2","3+"].map(b=>{ const on=beds.includes(b); return (
                    <button key={b} onClick={()=>setBeds(prev=>prev.includes(b)?prev.filter(x=>x!==b):[...prev,b])} style={fChip(on)}>{b==="Studio"?t.flt.studio:b}</button>
                  );})}
                </div>
              </div>
              <div>
                <label style={fLabel}>{t.flt.price}<span style={{ fontWeight:500, color:"#A89580", textTransform:"none", letterSpacing:0 }}> ({status==="For Sale"?"฿":"฿/mo"})</span></label>
                <div style={{ display:"flex", gap:8 }}>
                  <input type="text" inputMode="numeric" placeholder={t.flt.min} value={priceMin} onChange={e=>setPriceMin(e.target.value)} style={fNum}/>
                  <input type="text" inputMode="numeric" placeholder={t.flt.max} value={priceMax} onChange={e=>setPriceMax(e.target.value)} style={fNum}/>
                </div>
              </div>
              <div>
                <label style={fLabel}>{t.flt.size}</label>
                <div style={{ display:"flex", gap:8 }}>
                  <input type="text" inputMode="numeric" placeholder={t.flt.min} value={sizeMin} onChange={e=>setSizeMin(e.target.value)} style={fNum}/>
                  <input type="text" inputMode="numeric" placeholder={t.flt.max} value={sizeMax} onChange={e=>setSizeMax(e.target.value)} style={fNum}/>
                </div>
              </div>
              <div>
                <label style={fLabel}>{t.flt.zone}</label>
                <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                  <select value={line} onChange={e=>{ setLine(e.target.value); setStation("All Stations"); }} style={{...fNum, cursor:"pointer"}}>
                    {lineOptions.map(l=><option key={l}>{l}</option>)}
                  </select>
                  <select value={station} onChange={e=>setStation(e.target.value)} style={{...fNum, cursor:"pointer"}}>
                    <option>All Stations</option>
                    {line!=="All Lines" ? (TRANSIT_LINES[line]||[]).map(st=><option key={st}>{st}</option>) : null}
                  </select>
                </div>
              </div>
              <div>
                <label style={fLabel}>{t.flt.kw}</label>
                <input type="text" placeholder={t.flt.kwPh} value={q} onChange={e=>setQ(e.target.value)} style={fNum}/>
              </div>
            </div>
            <div style={{ display:"flex", justifyContent:"flex-end", gap:10, marginTop:18 }}>
              <button onClick={clearFilters} style={{ background:"transparent", border:"1px solid #E5DDD3", color:"#7B6A5A", borderRadius:10, padding:"9px 18px", fontSize:13, fontWeight:700, cursor:"pointer" }}>{t.flt.clear}</button>
              <button onClick={()=>setShowFilters(false)} className="bpf-fapply" style={{ display:"none", background:"linear-gradient(135deg,#C9A96E,#9B6B2A)", color:"#fff", border:"none", borderRadius:10, padding:"9px 22px", fontSize:13, fontWeight:700, cursor:"pointer" }}>{t.flt.apply}</button>
            </div>
          </div>
        </div>

        {activeChips.length>0 && (
          <div style={{ display:"flex", flexWrap:"wrap", gap:8, marginBottom:22, alignItems:"center" }}>
            {activeChips.map(ch=>(
              <button key={ch.k} onClick={ch.on} style={{ display:"inline-flex", alignItems:"center", gap:6, background:"#FBF3E6", color:"#9B6B2A", border:"1px solid #E8D9BE", borderRadius:20, padding:"5px 12px", fontSize:12, fontWeight:600, cursor:"pointer" }}>{ch.label} <span style={{ fontSize:15, lineHeight:1 }}>×</span></button>
            ))}
            <button onClick={clearFilters} style={{ background:"transparent", border:"none", color:"#7B6A5A", fontSize:12, fontWeight:700, cursor:"pointer", textDecoration:"underline" }}>{t.flt.clear}</button>
          </div>
        )}

        {view==="map" ? (
          <MapView items={shown} onOpen={openDetail} lang={lang} />
        ) : shown.length===0 ? (
          <div style={{ textAlign:"center", padding:"60px 20px", color:"#A89580" }}>
            <div style={{ marginBottom:12, display:"flex", justifyContent:"center" }}><Icon n="search" s={42} c="#D9CFC2"/></div>
            <div style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:24, marginBottom:6 }}>{t.emptyTitle}</div>
            <div style={{ fontSize:13 }}>{t.emptySub}</div>
          </div>
        ) : (
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(300px,1fr))", gap:22 }}>
            {shown.map((p,i)=><Card key={p.id} p={p} idx={i} isAdmin={isAdmin} onEdit={onEditProp} onDel={onDelProp} agentContacts={agentContacts} onOpen={openDetail}/>)}
          </div>
        )}
        {selectedId && (()=>{ const sp = props.find(p => String(p.id)===String(selectedId) && p.active!==false && p.approved!=="0"); return sp ? <PropDetail p={sp} onClose={closeDetail} agentContacts={agentContacts}/> : null; })()}
      </section>

      {/* ABOUT */}
      <section id="rent" style={{ background:"linear-gradient(135deg,#1C1410 0%,#2E1E0E 100%)", padding:"72px clamp(20px,5vw,60px)" }}>
        <div style={{ maxWidth:1200, margin:"0 auto", display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))", gap:48, alignItems:"center" }}>
          <div>
            <div style={{ color:"#F59E0B", fontSize:10, fontWeight:700, letterSpacing:"0.15em", textTransform:"uppercase", marginBottom:12 }}>{t.meet}</div>
            <h2 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:"clamp(28px,4vw,46px)", fontWeight:700, color:"#F5E9D0", marginBottom:16 }}>
              {t.aboutH2a}<br/><em style={{ color:"#C9A96E" }}>{t.aboutH2b}</em>
            </h2>
            <p style={{ color:"#8E7E6E", lineHeight:1.85, fontSize:14, marginBottom:22 }}>
              {t.aboutP1}<strong style={{ color:"#C9A96E" }}>Annie</strong>{t.aboutP2}
            </p>
            <div style={{ display:"flex", flexDirection:"column", gap:11, marginBottom:26 }}>
              {t.aboutChecks.map(item=>(
                <div key={item} style={{ display:"flex", alignItems:"center", gap:11, color:"#D8C8B4", fontSize:14 }}>
                  <span style={{ width:22, height:22, borderRadius:"50%", background:"rgba(201,169,110,0.18)", color:"#C9A96E", display:"inline-flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:800, flexShrink:0 }}>✓</span>
                  {item}
                </div>
              ))}
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:11 }}>
              <div style={{ color:"#C0B0A0", fontSize:14, display:"flex", alignItems:"center", gap:8 }}><Icon n="phone" s={15} c="#C9A96E"/>{OWNER.phoneDisplay}</div>
              <div style={{ color:"#C0B0A0", fontSize:14, display:"flex", alignItems:"center", gap:8 }}><Icon n="mail" s={15} c="#C9A96E"/>{OWNER.email}</div>
              <a href={OWNER.igUrl} target="_blank" rel="noreferrer" style={{ color:"#C0B0A0", fontSize:14, textDecoration:"none" }}><span style={{ display:"inline-flex", alignItems:"center", gap:5 }}><Icon n="instagram" s={14} c="#C0B0A0"/>@{OWNER.ig}</span></a>
              <a href={OWNER.fbUrl} target="_blank" rel="noreferrer" style={{ color:"#C0B0A0", fontSize:14, textDecoration:"none" }}><span style={{ display:"inline-flex", alignItems:"center", gap:5 }}><Icon n="facebook" s={14} c="#C0B0A0"/>{OWNER.fb}</span></a>
              <div style={{ display:"flex", gap:10, marginTop:4 }}>
                <a href={`https://wa.me/${OWNER.whatsapp}`} target="_blank" rel="noreferrer"
                  style={{ textDecoration:"none", background:"#25D366", color:"#fff", padding:"9px 18px", borderRadius:11, fontSize:13, fontWeight:700, display:"flex", alignItems:"center", gap:6 }}>
                  <span style={{ display:"inline-flex", alignItems:"center", gap:7, justifyContent:"center" }}><Icon n="chat" s={15} c="#fff"/>WhatsApp</span>
                </a>
                <a href={OWNER.lineUrl} target="_blank" rel="noreferrer"
                  style={{ textDecoration:"none", background:"#06C755", color:"#fff", padding:"9px 18px", borderRadius:11, fontSize:13, fontWeight:700, display:"flex", alignItems:"center", gap:6 }}>
                  <span style={{ display:"inline-flex", alignItems:"center", gap:7, justifyContent:"center" }}><Icon n="line" s={15} c="#fff"/>Line</span>
                </a>
              </div>
            </div>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:13 }}>
            {t.aboutCards.map((c,i)=>(
              <div key={i} style={{ background:"rgba(255,255,255,0.04)", border:"1px solid rgba(201,169,110,0.14)", borderRadius:14, padding:"20px 16px", transition:"all 0.22s" }}
                onMouseEnter={e=>{ e.currentTarget.style.background="rgba(201,169,110,0.08)"; e.currentTarget.style.borderColor="rgba(201,169,110,0.38)"; }}
                onMouseLeave={e=>{ e.currentTarget.style.background="rgba(255,255,255,0.04)"; e.currentTarget.style.borderColor="rgba(201,169,110,0.14)"; }}>
                <div style={{ marginBottom:11 }}><Icon n={["shield","globe","zap","star"][i]} s={24} c="#C9A96E"/></div>
                <div style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:16, fontWeight:700, color:"#F5E9D0", marginBottom:5 }}>{c.t}</div>
                <div style={{ color:"#8E7E6E", fontSize:12, lineHeight:1.6 }}>{c.d}</div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* CITIES */}
      <section style={{ padding:"72px clamp(20px,5vw,60px)", maxWidth:1200, margin:"0 auto" }}>
        <div style={{ textAlign:"center", marginBottom:36 }}>
          <div style={{ color:"#F59E0B", fontSize:10, fontWeight:700, letterSpacing:"0.15em", textTransform:"uppercase", marginBottom:10 }}>{t.explore}</div>
          <h2 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:"clamp(26px,4vw,44px)", fontWeight:700, color:"#1C1410" }}>{t.browse}</h2>
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(170px,1fr))", gap:18 }}>
          {[{c:"Bangkok",img:"https://images.unsplash.com/photo-1755251042986-91270ffd76f5?w=700&q=85"},{c:"Phuket",img:"https://images.unsplash.com/photo-1534008897995-27a23e859048?w=700&q=85"},{c:"Chiang Mai",img:"https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=700&q=85"},{c:"Pattaya",img:"https://images.unsplash.com/photo-1563245372-f21724e3856d?w=700&q=85"},{c:"Hua Hin",img:"https://images.unsplash.com/photo-1552465011-b4e21bf6e79a?w=700&q=85"},{c:"Koh Samui",img:"https://images.unsplash.com/photo-1537956965359-7573183d1f57?w=700&q=85"}].map((x,i)=>(
            <div key={i} onClick={()=>{ setCity(x.c); document.getElementById("buy")?.scrollIntoView({behavior:"smooth"}); }} style={{ position:"relative", borderRadius:18, overflow:"hidden", cursor:"pointer", aspectRatio:"4/5", border:city===x.c?"2px solid #C9A96E":"2px solid transparent", boxShadow:city===x.c?"0 12px 32px rgba(201,169,110,0.35)":"0 6px 20px rgba(0,0,0,0.12)", transition:"all 0.35s cubic-bezier(0.22,1,0.36,1)" }}
              onMouseEnter={e=>{ e.currentTarget.style.transform="translateY(-6px)"; e.currentTarget.style.boxShadow="0 18px 40px rgba(201,169,110,0.4)"; const img=e.currentTarget.querySelector("img"); if(img) img.style.transform="scale(1.1)"; const ex=e.currentTarget.querySelector(".explore"); if(ex) ex.style.opacity="1"; }}
              onMouseLeave={e=>{ e.currentTarget.style.transform="translateY(0)"; e.currentTarget.style.boxShadow=city===x.c?"0 12px 32px rgba(201,169,110,0.35)":"0 6px 20px rgba(0,0,0,0.12)"; const img=e.currentTarget.querySelector("img"); if(img) img.style.transform="scale(1)"; const ex=e.currentTarget.querySelector(".explore"); if(ex) ex.style.opacity="0"; }}>
              <img src={cityPhotos[x.c] || x.img} alt={x.c} style={{ width:"100%", height:"100%", objectFit:"cover", transition:"transform 0.55s cubic-bezier(0.22,1,0.36,1)", filter:"saturate(1.05) brightness(0.98)" }}/>
              <div style={{ position:"absolute", inset:0, background:"linear-gradient(160deg, rgba(120,72,30,0.28) 0%, rgba(40,24,12,0.15) 40%, rgba(20,12,6,0.55) 100%)", mixBlendMode:"multiply" }}/>
              <div style={{ position:"absolute", inset:0, background:"linear-gradient(to top, rgba(20,12,6,0.92) 0%, rgba(40,24,12,0.32) 48%, rgba(201,169,110,0.18) 100%)" }}/>
              <div style={{ position:"absolute", bottom:16, left:16, right:16 }}>
                <div style={{ width:28, height:2, background:"#C9A96E", marginBottom:8, borderRadius:2 }}/>
                <div style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:21, fontWeight:700, color:"#fff", letterSpacing:"0.02em", lineHeight:1.1 }}>{x.c}</div>
                <div style={{ color:"#D9BC8A", fontSize:11, fontWeight:600, marginTop:3, letterSpacing:"0.05em" }}>{(()=>{ const n = props.filter(p=>p.active!==false && p.approved!=="0" && p.location.toLowerCase().includes(x.c.toLowerCase())).length; return n + " " + (n===1?t.listingOne:t.listingMany); })()}</div>
                <div className="explore" style={{ color:"#fff", fontSize:11, fontWeight:600, marginTop:8, opacity:0, transition:"opacity 0.3s", letterSpacing:"0.08em", textTransform:"uppercase" }}>{t.exploreMore}</div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* SERVICES */}
      <section id="services" style={{ background:"linear-gradient(135deg,#1C1410 0%,#2E1E0E 100%)", padding:"72px clamp(20px,5vw,60px)" }}>
        <div style={{ maxWidth:1100, margin:"0 auto" }}>
          <div style={{ textAlign:"center", marginBottom:44 }}>
            <div style={{ color:"#C9A96E", fontSize:11, fontWeight:700, letterSpacing:"0.15em", textTransform:"uppercase", marginBottom:10 }}>{t.offer}</div>
            <h2 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:"clamp(28px,4vw,46px)", fontWeight:700, color:"#fff", margin:0 }}>{t.ourServices}</h2>
            <p style={{ color:"rgba(255,255,255,0.6)", fontSize:15, marginTop:12, maxWidth:560, marginLeft:"auto", marginRight:"auto", lineHeight:1.6 }}>{t.servicesSub}</p>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(240px,1fr))", gap:20 }}>
            {[ { icon:"search" }, { icon:"bulb" }, { icon:"target" } ].map((s,i)=>(
              <div key={i} style={{ background:"rgba(255,255,255,0.05)", border:"1px solid rgba(201,169,110,0.25)", borderRadius:16, padding:"28px 24px", transition:"all 0.22s" }}
                onMouseEnter={e=>{ e.currentTarget.style.background="rgba(255,255,255,0.08)"; e.currentTarget.style.transform="translateY(-4px)"; }}
                onMouseLeave={e=>{ e.currentTarget.style.background="rgba(255,255,255,0.05)"; e.currentTarget.style.transform="translateY(0)"; }}>
                <div style={{ marginBottom:16, width:52, height:52, borderRadius:14, background:"rgba(201,169,110,0.12)", display:"flex", alignItems:"center", justifyContent:"center" }}><Icon n={s.icon} s={26} c="#C9A96E"/></div>
                <h3 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:23, fontWeight:700, color:"#C9A96E", margin:"0 0 10px" }}>{t.serviceCards[i].title}</h3>
                <p style={{ color:"rgba(255,255,255,0.7)", fontSize:14, lineHeight:1.6, margin:0 }}>{t.serviceCards[i].desc}</p>
              </div>
            ))}
          </div>
          <div style={{ textAlign:"center", marginTop:40 }}>
            <p style={{ color:"#fff", fontSize:18, fontFamily:"'Cormorant Garamond',serif", fontWeight:600, marginBottom:18 }}>{t.cantFind}</p>
            <div style={{ display:"flex", gap:12, justifyContent:"center", flexWrap:"wrap" }}>
              <a href={OWNER.lineUrl} target="_blank" rel="noreferrer"
                style={{ display:"inline-flex", alignItems:"center", gap:9, textDecoration:"none", background:"#06C755", color:"#fff", padding:"14px 30px", borderRadius:12, fontSize:15, fontWeight:700 }}>
                <span style={{ display:"inline-flex", alignItems:"center", gap:8 }}><Icon n="line" s={16} c="#fff"/>{t.addLine}</span>
              </a>
              <a href={"https://wa.me/" + OWNER.whatsapp} target="_blank" rel="noreferrer"
                style={{ display:"inline-flex", alignItems:"center", gap:9, textDecoration:"none", background:"#25D366", color:"#fff", padding:"14px 30px", borderRadius:12, fontSize:15, fontWeight:700 }}>
                <span style={{ display:"inline-flex", alignItems:"center", gap:7, justifyContent:"center" }}><Icon n="chat" s={15} c="#fff"/>WhatsApp</span>
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* GUIDES */}
      <section id="guides" style={{ background:"#FDFAF6", padding:"72px clamp(20px,5vw,60px)" }}>
        <div style={{ maxWidth:1100, margin:"0 auto" }}>
          <div style={{ textAlign:"center", marginBottom:44 }}>
            <div style={{ color:"#C9A96E", fontSize:11, fontWeight:700, letterSpacing:"0.18em", textTransform:"uppercase", marginBottom:12 }}>{t.guidesTag}</div>
            <h2 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:"clamp(28px,4vw,44px)", fontWeight:700, color:"#1C1410", marginBottom:12 }}>{t.guidesH2a} <em style={{ color:"#C9A96E" }}>{t.guidesH2b}</em></h2>
            <p style={{ color:"#8E7E6E", fontSize:15, maxWidth:560, margin:"0 auto", lineHeight:1.7 }}>{t.guidesSub}</p>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(300px,1fr))", gap:18, alignItems:"start" }}>
            {guides.map((g,i)=>{
              const open = openGuide===i;
              return (
                <div key={i} onClick={()=>setOpenGuide(open?null:i)} style={{ background:"#fff", border:"1px solid #EFE8DF", borderRadius:18, padding:"24px", boxShadow: open?"0 12px 36px rgba(28,20,16,0.1)":"0 2px 14px rgba(0,0,0,0.04)", transition:"box-shadow 0.25s", cursor:"pointer" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:13 }}>
                    <span style={{ width:40, height:40, borderRadius:12, background:"linear-gradient(135deg,#C9A96E,#9B6B2A)", display:"inline-flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}><Icon n={GUIDE_ICONS[i]} s={19} c="#fff"/></span>
                    <span style={{ fontSize:10.5, fontWeight:800, letterSpacing:"0.12em", textTransform:"uppercase", color:"#9B6B2A", background:"#FBF3E6", padding:"4px 10px", borderRadius:20 }}>{g.tag}</span>
                  </div>
                  <h3 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:23, fontWeight:700, color:"#1C1410", marginBottom:8, lineHeight:1.2 }}>{g.title}</h3>
                  <p style={{ color:"#8E7E6E", fontSize:13.5, lineHeight:1.6, marginBottom: open?18:0 }}>{g.intro}</p>
                  {open && (
                    <div style={{ display:"flex", flexDirection:"column", gap:14, borderTop:"1px solid #EFE8DF", paddingTop:16 }}>
                      {g.points.map((p,j)=>(
                        <div key={j} style={{ display:"flex", gap:11 }}>
                          <span style={{ width:24, height:24, borderRadius:"50%", background:"#FBF3E6", color:"#9B6B2A", fontSize:12, fontWeight:800, display:"inline-flex", alignItems:"center", justifyContent:"center", flexShrink:0, marginTop:1 }}>{j+1}</span>
                          <div><div style={{ fontWeight:700, fontSize:14, color:"#1C1410", marginBottom:3 }}>{p.h}</div><div style={{ color:"#6B5E52", fontSize:13.5, lineHeight:1.65 }}>{p.b}</div></div>
                        </div>
                      ))}
                    </div>
                  )}
                  <div style={{ marginTop:14, color:"#C9A96E", fontSize:13, fontWeight:700 }}>{open ? t.showLess : t.readMore}</div>
                </div>
              );
            })}
          </div>
          <div style={{ textAlign:"center", marginTop:36 }}>
            <p style={{ color:"#8E7E6E", fontSize:14, marginBottom:16 }}>{t.guidesQ}</p>
            <button onClick={()=>document.getElementById("contact")?.scrollIntoView({behavior:"smooth"})} style={{ background:"linear-gradient(135deg,#C9A96E,#9B6B2A)", color:"#fff", border:"none", padding:"13px 30px", borderRadius:30, fontSize:14, fontWeight:700, cursor:"pointer", boxShadow:"0 10px 30px rgba(201,169,110,0.3)" }}>{t.askAnnie}</button>
          </div>
        </div>
      </section>

      {/* CONTACT */}
      <section id="contact" style={{ background:"#F3EEE8", padding:"72px clamp(20px,5vw,60px)" }}>
        <div style={{ maxWidth:860, margin:"0 auto" }}>
          <div style={{ textAlign:"center", marginBottom:36 }}>
            <div style={{ color:"#F59E0B", fontSize:10, fontWeight:700, letterSpacing:"0.15em", textTransform:"uppercase", marginBottom:10 }}>{t.getInTouch}</div>
            <h2 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:"clamp(26px,4vw,44px)", fontWeight:700, color:"#1C1410" }}>{t.contactAnnie}</h2>
            <p style={{ color:"#7B6A5A", fontSize:14, marginTop:8 }}>{t.replies}</p>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(250px,1fr))", gap:26, alignItems:"start" }}>
            <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
              {[{e:"phone",l:t.lblPhone,v:OWNER.phoneDisplay},{e:"mail",l:t.lblEmail,v:OWNER.email}].map((r,i)=>(
                <div key={i} style={{ background:"#fff", borderRadius:13, padding:"15px 17px", display:"flex", alignItems:"center", gap:13, boxShadow:"0 2px 10px rgba(0,0,0,0.04)" }}>
                  <div style={{ width:40, height:40, borderRadius:"50%", background:"linear-gradient(135deg,#C9A96E,#9B6B2A)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}><Icon n={r.e} s={18} c="#fff"/></div>
                  <div>
                    <div style={{ fontSize:10, color:"#A89580", fontWeight:700, letterSpacing:"0.07em", textTransform:"uppercase" }}>{r.l}</div>
                    <div style={{ fontSize:13, color:"#1C1410", fontWeight:600, marginTop:2 }}>{r.v}</div>
                  </div>
                </div>
              ))}
              <a href={`https://wa.me/${OWNER.whatsapp}`} target="_blank" rel="noreferrer"
                style={{ textDecoration:"none", background:"#25D366", borderRadius:13, padding:"15px 17px", display:"flex", alignItems:"center", gap:13 }}>
                <div style={{ width:40, height:40, borderRadius:"50%", background:"rgba(255,255,255,0.25)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}><Icon n="chat" s={19} c="#fff"/></div>
                <div><div style={{ fontSize:10, color:"rgba(255,255,255,0.8)", fontWeight:700, textTransform:"uppercase" }}>WhatsApp</div><div style={{ fontSize:14, color:"#fff", fontWeight:700, marginTop:2 }}>+66 082 538 8189</div></div>
                <span style={{ marginLeft:"auto", color:"rgba(255,255,255,0.7)", fontSize:18 }}>↗</span>
              </a>
              <a href={OWNER.lineUrl} target="_blank" rel="noreferrer"
                style={{ textDecoration:"none", background:"#06C755", borderRadius:13, padding:"15px 17px", display:"flex", alignItems:"center", gap:13 }}>
                <div style={{ width:40, height:40, borderRadius:"50%", background:"rgba(255,255,255,0.25)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}><Icon n="line" s={19} c="#fff"/></div>
                <div><div style={{ fontSize:10, color:"rgba(255,255,255,0.8)", fontWeight:700, textTransform:"uppercase" }}>Line</div><div style={{ fontSize:14, color:"#fff", fontWeight:700, marginTop:2 }}>ID: {OWNER.lineId}</div></div>
                <span style={{ marginLeft:"auto", color:"rgba(255,255,255,0.7)", fontSize:18 }}>↗</span>
              </a>
              <a href={OWNER.igUrl} target="_blank" rel="noreferrer"
                style={{ textDecoration:"none", background:"linear-gradient(135deg,#f09433,#dc2743,#bc1888)", borderRadius:13, padding:"15px 17px", display:"flex", alignItems:"center", gap:13 }}>
                <div style={{ width:40, height:40, borderRadius:"50%", background:"rgba(255,255,255,0.2)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}><Icon n="instagram" s={19} c="#fff"/></div>
                <div><div style={{ fontSize:10, color:"rgba(255,255,255,0.7)", fontWeight:700, textTransform:"uppercase" }}>Instagram</div><div style={{ fontSize:14, color:"#fff", fontWeight:700, marginTop:2 }}>@{OWNER.ig}</div></div>
                <span style={{ marginLeft:"auto", color:"rgba(255,255,255,0.7)", fontSize:18 }}>↗</span>
              </a>
              <a href={OWNER.fbUrl} target="_blank" rel="noreferrer"
                style={{ textDecoration:"none", background:"linear-gradient(135deg,#1877F2,#0A56C2)", borderRadius:13, padding:"15px 17px", display:"flex", alignItems:"center", gap:13 }}>
                <div style={{ width:40, height:40, borderRadius:"50%", background:"rgba(255,255,255,0.2)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}><Icon n="facebook" s={19} c="#fff"/></div>
                <div><div style={{ fontSize:10, color:"rgba(255,255,255,0.7)", fontWeight:700, textTransform:"uppercase" }}>Facebook</div><div style={{ fontSize:14, color:"#fff", fontWeight:700, marginTop:2 }}>{OWNER.fb}</div></div>
                <span style={{ marginLeft:"auto", color:"rgba(255,255,255,0.7)", fontSize:18 }}>↗</span>
              </a>
            </div>
            <div style={{ background:"#fff", borderRadius:18, padding:"26px 22px", boxShadow:"0 6px 28px rgba(0,0,0,0.07)" }}>
              {sent ? (
                <div style={{ textAlign:"center", padding:"30px 10px" }}>
                  <div style={{ fontSize:44, marginBottom:12 }}>✅</div>
                  <div style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:22, fontWeight:700, marginBottom:6 }}>{t.sentTitle}</div>
                  <p style={{ color:"#7B6A5A", fontSize:13, marginBottom:16 }}>{t.sentSub}</p>
                  <button onClick={()=>setSent(false)} style={{ background:"#F3EEE8", color:"#6B5E52", border:"none", padding:"8px 18px", borderRadius:10, fontSize:13, fontWeight:600, cursor:"pointer" }}>{t.sendAnother}</button>
                </div>
              ) : (
                <>
                  <h3 style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:23, fontWeight:700, color:"#1C1410", marginBottom:6 }}>{t.formTitle}</h3>
                  <p style={{ color:"#7B6A5A", fontSize:13, marginBottom:18 }}>{t.formSub}</p>
                  <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
                    {[{l:t.fName,k:"name",t:"text",ph:t.fNamePh},{l:t.fEmail,k:"email",t:"email",ph:t.fEmailPh},{l:t.fPhone,k:"phone",t:"text",ph:t.fPhonePh},{l:t.fBudget,k:"budget",t:"text",ph:t.fBudgetPh},{l:t.fLoc,k:"location",t:"text",ph:t.fLocPh}].map(field=>(
                      <div key={field.k}>
                        <label style={{ fontSize:11, fontWeight:700, color:"#7B6A5A", letterSpacing:"0.07em", textTransform:"uppercase", display:"block", marginBottom:5 }}>{field.l}</label>
                        <input type={field.t} placeholder={field.ph} value={contact[field.k]} onChange={e=>setContact({...contact,[field.k]:e.target.value})} style={S.inp()} onFocus={onFG} onBlur={onBG}/>
                      </div>
                    ))}
                    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12 }}>
                      <div>
                        <label style={{ fontSize:11, fontWeight:700, color:"#7B6A5A", letterSpacing:"0.07em", textTransform:"uppercase", display:"block", marginBottom:5 }}>{t.fBeds}</label>
                        <select value={contact.beds} onChange={e=>setContact({...contact,beds:e.target.value})} style={S.inp({cursor:"pointer"})}>
                          {["Any","Studio","1","2","3","4+"].map(b=><option key={b}>{b}</option>)}
                        </select>
                      </div>
                      <div>
                        <label style={{ fontSize:11, fontWeight:700, color:"#7B6A5A", letterSpacing:"0.07em", textTransform:"uppercase", display:"block", marginBottom:5 }}>{t.fMove}</label>
                        <input type="text" placeholder={t.fMovePh} value={contact.movein} onChange={e=>setContact({...contact,movein:e.target.value})} style={S.inp()} onFocus={onFG} onBlur={onBG}/>
                      </div>
                    </div>
                    <div>
                      <label style={{ fontSize:11, fontWeight:700, color:"#7B6A5A", letterSpacing:"0.07em", textTransform:"uppercase", display:"block", marginBottom:5 }}>{t.fMsg}</label>
                      <textarea rows={3} placeholder={t.fMsgPh} value={contact.msg} onChange={e=>setContact({...contact,msg:e.target.value})} style={{...S.inp(),resize:"vertical"}} onFocus={onFG} onBlur={onBG}/>
                    </div>
                    <button onClick={()=>{
                      if(!contact.name || !(contact.email||contact.phone)){ alert(t.formAlert); return; }
                      const lines=["Hi Annie! I'm looking for a property 🏡",""];
                      lines.push("Name: "+contact.name);
                      if(contact.budget) lines.push("Budget: "+contact.budget);
                      if(contact.location) lines.push("Preferred area: "+contact.location);
                      if(contact.beds && contact.beds!=="Any") lines.push("Bedrooms: "+contact.beds);
                      if(contact.movein) lines.push("Move-in: "+contact.movein);
                      lines.push("");
                      if(contact.email) lines.push("Email: "+contact.email);
                      if(contact.phone) lines.push("Phone/LINE: "+contact.phone);
                      if(contact.msg){ lines.push(""); lines.push("Message: "+contact.msg); }
                      lines.push(""); lines.push("(Sent from bangkokpropertyfinder.vercel.app)");
                      window.open("https://wa.me/"+OWNER.whatsapp+"?text="+encodeURIComponent(lines.join("\n")), "_blank");
                      setSent(true);
                    }} style={{...S.gold,width:"100%",padding:"13px",fontSize:14}}>
                      {t.sendBtn}
                    </button>
                    <p style={{ fontSize:11, color:"#A89580", textAlign:"center" }}>{t.sendNote}</p>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      </section>

      <div className="bpf-mbar" style={{ position:"fixed", bottom:0, left:0, right:0, zIndex:600, background:"rgba(28,16,8,0.97)", backdropFilter:"blur(10px)", borderTop:"1px solid rgba(201,169,110,0.25)", padding:"8px", gap:8, boxShadow:"0 -4px 20px rgba(0,0,0,0.3)" }}>
        <a href={OWNER.lineUrl} target="_blank" rel="noreferrer" style={{ flex:1, textDecoration:"none", background:"#06C755", color:"#fff", borderRadius:11, padding:"12px", display:"flex", alignItems:"center", justifyContent:"center", gap:7, fontSize:14, fontWeight:700 }}><Icon n="line" s={18} c="#fff"/>LINE</a>
        <a href={`https://wa.me/${OWNER.whatsapp}`} target="_blank" rel="noreferrer" style={{ flex:1, textDecoration:"none", background:"#25D366", color:"#fff", borderRadius:11, padding:"12px", display:"flex", alignItems:"center", justifyContent:"center", gap:7, fontSize:14, fontWeight:700 }}><Icon n="chat" s={18} c="#fff"/>WhatsApp</a>
        <button onClick={()=>window.scrollTo({top:0, behavior:"smooth"})} style={{ flex:1, border:"none", background:"linear-gradient(135deg,#C9A96E,#9B6B2A)", color:"#fff", borderRadius:11, padding:"12px", display:"flex", alignItems:"center", justifyContent:"center", gap:7, fontSize:14, fontWeight:700, cursor:"pointer" }}><Icon n="search" s={17} c="#fff"/>{t.stickySearch}</button>
      </div>
      <div className="bpf-mbar-sp" style={{ height:64 }} />

      {/* FOOTER */}
      <footer style={{ background:"#0F0A04", padding:"56px clamp(20px,5vw,60px) 26px", borderTop:"1px solid rgba(201,169,110,0.12)" }}>
        <div style={{ maxWidth:1080, margin:"0 auto", display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(230px,1fr))", gap:40, alignItems:"start" }}>
          <div>
            <img src={LOGO_IMG} alt="Bangkok Property Finder" style={{ height:46, width:"auto", objectFit:"contain", marginBottom:14 }}/>
            <p style={{ color:"#7B6A5A", fontSize:13.5, lineHeight:1.7, maxWidth:280, margin:0 }}>{t.footerTag}</p>
          </div>
          <div>
            <div style={{ color:"#C9A96E", fontSize:11, fontWeight:700, letterSpacing:"0.15em", textTransform:"uppercase", marginBottom:16 }}>{t.getInTouch}</div>
            <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
              {[
                { icon:"phone", label:OWNER.phoneDisplay, href:"tel:"+OWNER.phone },
                { icon:"chat", label:"+66 082 538 8189", href:"https://wa.me/"+OWNER.whatsapp },
                { icon:"line", label:"LINE "+OWNER.lineId, href:OWNER.lineUrl },
                { icon:"mail", label:OWNER.email, href:"mailto:"+OWNER.email },
                { icon:"instagram", label:"@"+OWNER.ig, href:OWNER.igUrl },
                { icon:"facebook", label:OWNER.fb, href:OWNER.fbUrl }
              ].map((m,i)=>(
                <a key={i} href={m.href} target="_blank" rel="noreferrer" style={{ display:"inline-flex", alignItems:"center", gap:11, textDecoration:"none", color:"#D8C8B4", fontSize:13.5 }}>
                  <span style={{ width:34, height:34, borderRadius:10, background:"rgba(201,169,110,0.12)", display:"inline-flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}><Icon n={m.icon} s={16} c="#C9A96E"/></span>
                  {m.label}
                </a>
              ))}
            </div>
          </div>
          <div>
            <div style={{ color:"#C9A96E", fontSize:11, fontWeight:700, letterSpacing:"0.15em", textTransform:"uppercase", marginBottom:16 }}>{t.addMeLine}</div>
            <div style={{ background:"#fff", padding:12, borderRadius:16, boxShadow:"0 8px 24px rgba(0,0,0,0.3)", display:"inline-block" }}>
              <img src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&margin=0&data=${encodeURIComponent(OWNER.lineUrl)}`} alt="Scan to add Annie on LINE" width={140} height={140} style={{ display:"block", width:140, height:140 }}/>
            </div>
            <div style={{ color:"#7B6A5A", fontSize:12.5, marginTop:11, display:"inline-flex", alignItems:"center", gap:6 }}><Icon n="line" s={14} c="#06C755"/>{t.footerScan}</div>
          </div>
        </div>
        <div style={{ maxWidth:1080, margin:"40px auto 0", paddingTop:22, borderTop:"1px solid rgba(201,169,110,0.1)", color:"#4A3A2A", fontSize:12, textAlign:"center" }}>© 2026 Bangkok Property Finder · Real Estate By Annie · Bangkok, Thailand</div>
      </footer>
    </div>
  );
}

export default function App() {
  const [screen, setScreen]     = useState(() => { try { return localStorage.getItem("bpf_screen") === "admin" ? "admin" : "site"; } catch { return "site"; } });
  const [props, setProps]       = useState(() => {
    try { const s = localStorage.getItem("bangkokpropertyfinder_props"); return s ? JSON.parse(s) : []; } catch { return []; }
  });
  const [dbLoading, setDbLoading] = useState(SB_ON);
  const [form, setForm]         = useState(null);
  const [delId, setDelId]       = useState(null);
  const [toast, setToast]       = useState(null);
  const [adminView, setAdminView] = useState(false);
  const [cityPhotos, setCityPhotos] = useState(()=>{ try { return JSON.parse(localStorage.getItem("bpf_city_photos")||"{}"); } catch { return {}; } });
  const [cityRowId, setCityRowId] = useState(null);
  const [visits, setVisits] = useState(0);
  const [statsRowId, setStatsRowId] = useState(null);
  const [agents, setAgents] = useState([]);
  const [agentsRowId, setAgentsRowId] = useState(null);
  const [pending, setPending] = useState([]);
  const [pendingRowId, setPendingRowId] = useState(null);
  const [ownerCreds, setOwnerCreds] = useState({ user: ADMIN_USER, pass: ADMIN_PASS, name: "Annie", whatsapp: OWNER.whatsapp, line: OWNER.lineUrl, phone: OWNER.phoneDisplay });
  const [ownerRowId, setOwnerRowId] = useState(null);
  const [currentUser, setCurrentUser] = useState(()=>{ try { return JSON.parse(localStorage.getItem("bpf_user")||"null"); } catch { return null; } });

  useEffect(() => {
    if (!SB_ON) {
      const s = localStorage.getItem("bangkokpropertyfinder_props");
      if (!s || JSON.parse(s).length === 0) setProps(SEED);
      setDbLoading(false);
      return;
    }
    sbLoad().then(data => {
      if (data && Array.isArray(data)) {
        const cpRow = data.find(p => p.type === "__city_photos__");
        if (cpRow) { setCityRowId(cpRow.id); try { const m = JSON.parse(cpRow.facilities||"{}"); setCityPhotos(m); localStorage.setItem("bpf_city_photos", JSON.stringify(m)); } catch(_) {} }
        const stRow = data.find(p => p.type === "__stats__");
        if (stRow) { setStatsRowId(stRow.id); setVisits(parseInt(stRow.facilities||"0",10)||0); }
        const agRow = data.find(p => p.type === "__agents__");
        if (agRow) { setAgentsRowId(agRow.id); try { setAgents(JSON.parse(agRow.facilities||"[]")); } catch(_) {} }
        const pdRow = data.find(p => p.type === "__pending__");
        if (pdRow) { setPendingRowId(pdRow.id); try { setPending(JSON.parse(pdRow.facilities||"[]")); } catch(_) {} }
        const owRow = data.find(p => p.type === "__owner__");
        if (owRow) { setOwnerRowId(owRow.id); try { const oc = JSON.parse(owRow.facilities||"{}"); if (oc && oc.user) setOwnerCreds({ user:oc.user, pass:oc.pass, name:oc.name||"Annie", whatsapp:(oc.whatsapp!==undefined?oc.whatsapp:OWNER.whatsapp), line:(oc.line!==undefined?oc.line:OWNER.lineUrl), phone:(oc.phone!==undefined?oc.phone:OWNER.phoneDisplay) }); } catch(_) {} }
        const listings = data.filter(p => p.type !== "__city_photos__" && p.type !== "__stats__" && p.type !== "__agents__" && p.type !== "__pending__" && p.type !== "__owner__");
        setProps(listings);
        try { localStorage.setItem("bangkokpropertyfinder_props", JSON.stringify(listings)); } catch(_) {}
      }
      setDbLoading(false);
    });
  }, []);

  // Count one visit per browser session
  useEffect(() => {
    if (!SB_ON || dbLoading) return;
    try { if (sessionStorage.getItem("bpf_counted")) return; sessionStorage.setItem("bpf_counted","1"); } catch(_) { return; }
    const n = (visits||0) + 1; setVisits(n);
    (async () => {
      if (statsRowId) { await sbUpdate(statsRowId, { title:"__STATS__", type:"__stats__", active:false, facilities:String(n) }); }
      else { const s = await sbAdd({ title:"__STATS__", type:"__stats__", active:false, facilities:String(n) }); if (s) setStatsRowId(s.id); }
    })();
  }, [dbLoading]);

  useEffect(() => {
    if (!dbLoading) {
      try { localStorage.setItem("bangkokpropertyfinder_props", JSON.stringify(props)); } catch (_) {}
    }
  }, [props, dbLoading]);

  const flash = (msg) => { setToast(msg); setTimeout(() => setToast(null), 3000); };

  const handleToggle = async (id) => {
    const prop = props.find(p => p.id === id);
    const newActive = prop?.active === false ? true : false;
    const updated = props.map(p => p.id === id ? {...p, active: newActive} : p);
    setProps(updated);
    if (SB_ON) await sbUpdate(id, { active: newActive });
    flash(newActive ? "🟢 Listing is now Visible!" : "🔴 Listing is now Hidden!");
  };

  const handleSetMaplink = async (id, maplink) => {
    setProps(prev => prev.map(p => p.id === id ? { ...p, maplink } : p));
    if (SB_ON) return await sbUpdate(id, { maplink });
    return true;
  };

  const handleAIFill = (data) => {
    setForm({ ...data, id: null, imgs: [], img: "" });
  };

  const handleImportCSV = async (imported) => {
    const newItems = imported.filter(i => !props.find(p => p.title === i.title));
    const merged = [...newItems, ...props];
    setProps(merged);
    if (SB_ON && newItems.length > 0) await sbBulk(newItems.map(({id,...d}) => d));
    flash("✅ Imported " + imported.length + " listings successfully!");
  };

  const handleSave = async (data) => {
    if (form && form.id) {
      setProps(props.map(p => p.id === form.id ? { ...data, id: p.id } : p));
      if (SB_ON) await sbUpdate(form.id, data);
      flash("✅ Property updated!");
    } else {
      const isOwner = currentUser && currentUser.role === "owner";
      const d2 = { ...data, approved: isOwner ? "1" : "0" };
      const tempId = Date.now();
      setProps([{ ...d2, id: tempId, active: true }, ...props]);
      if (SB_ON) {
        const saved = await sbAdd({ ...d2, active: true });
        if (saved) setProps(prev => prev.map(p => p.id === tempId ? { ...p, id: saved.id } : p));
      }
      flash(isOwner ? "✅ Property added & live!" : "✅ Submitted! Annie will review & approve it before it goes live.");
    }
    setForm(null);
  };

  const handleApproveListing = async (id) => {
    setProps(props.map(p => p.id === id ? { ...p, approved:"1" } : p));
    if (SB_ON) await sbUpdate(id, { approved:"1" });
    flash("✅ Listing approved — now live on the website!");
  };

  const confirmDel = async () => {
    const id = delId;
    setProps(props.filter(p => p.id !== id));
    setDelId(null);
    if (SB_ON) await sbDelete(id);
    flash("🗑️ Listing deleted.");
  };

  const handleCityPhoto = async (cityName, url) => {
    const updated = { ...cityPhotos, [cityName]: url };
    setCityPhotos(updated);
    try { localStorage.setItem("bpf_city_photos", JSON.stringify(updated)); } catch(_) {}
    if (SB_ON) {
      const payload = { title:"__CITY_PHOTOS__", type:"__city_photos__", active:false, facilities: JSON.stringify(updated), location:"", price:"", status:"", beds:"", baths:"", sqm:"" };
      if (cityRowId) { await sbUpdate(cityRowId, payload); }
      else { const saved = await sbAdd(payload); if (saved) setCityRowId(saved.id); }
    }
    flash("✅ " + cityName + " photo updated!");
  };

  const handleAgents = async (newAgents) => {
    setAgents(newAgents);
    if (SB_ON) {
      const payload = { title:"__AGENTS__", type:"__agents__", active:false, facilities: JSON.stringify(newAgents), location:"", price:"", status:"", beds:"", baths:"", sqm:"" };
      if (agentsRowId) { await sbUpdate(agentsRowId, payload); }
      else { const saved = await sbAdd(payload); if (saved) setAgentsRowId(saved.id); }
    }
  };

  const savePending = async (np) => {
    setPending(np);
    if (SB_ON) {
      const payload = { title:"__PENDING__", type:"__pending__", active:false, facilities: JSON.stringify(np), location:"", price:"", status:"", beds:"", baths:"", sqm:"" };
      if (pendingRowId) { await sbUpdate(pendingRowId, payload); }
      else { const saved = await sbAdd(payload); if (saved) setPendingRowId(saved.id); }
    }
  };
  const handleApply = async (applicant) => { await savePending([...(pending||[]), applicant]); };
  const handleAgentSelfUpdate = async (oldName, oldUser, record) => {
    const newAgents = (agents||[]).map(a => (a.user===oldUser && a.name===oldName) ? record : a);
    await handleAgents(newAgents);
    if (record.name && record.name !== oldName) {
      const affected = props.filter(p => p.agent === oldName);
      setProps(props.map(p => p.agent === oldName ? { ...p, agent: record.name } : p));
      if (SB_ON) { for (const ap of affected) { await sbUpdate(ap.id, { agent: record.name }); } }
    }
    setCurrentUser(cu => { if (!cu) return cu; const n = { ...cu, name: record.name, user: record.user }; try { localStorage.setItem("bpf_user", JSON.stringify(n)); } catch(_) {} return n; });
  };
  const handleOwnerSelfUpdate = async (oldName, profile) => {
    setOwnerCreds(profile);
    if (SB_ON) {
      const payload = { title:"__OWNER__", type:"__owner__", active:false, facilities: JSON.stringify(profile), location:"", price:"", status:"", beds:"", baths:"", sqm:"" };
      if (ownerRowId) { await sbUpdate(ownerRowId, payload); }
      else { const saved = await sbAdd(payload); if (saved) setOwnerRowId(saved.id); }
    }
    if (profile.name && profile.name !== oldName) {
      const affected = props.filter(p => p.agent === oldName);
      setProps(props.map(p => p.agent === oldName ? { ...p, agent: profile.name } : p));
      if (SB_ON) { for (const ap of affected) { await sbUpdate(ap.id, { agent: profile.name }); } }
    }
    setCurrentUser(cu => { if (!cu) return cu; const n = { ...cu, name: profile.name, user: profile.user }; try { localStorage.setItem("bpf_user", JSON.stringify(n)); } catch(_) {} return n; });
  };
  const handleApprove = async (i) => {
    const ap = pending[i]; if (!ap) return;
    await handleAgents([...(agents||[]), { name:ap.name, user:ap.user, pass:ap.pass, whatsapp:ap.whatsapp||"", line:ap.line||"", phone:ap.phone||"" }]);
    await savePending(pending.filter((_,j)=>j!==i));
    flash("✅ " + ap.name + " approved — they can now log in!");
  };
  const handleReject = async (i) => { const ap = pending[i]; await savePending(pending.filter((_,j)=>j!==i)); flash("Removed " + (ap?ap.name+"\u2019s":"the") + " request"); };

  const agentContacts = {}; (agents||[]).forEach(a=>{ if(a&&a.name) agentContacts[a.name] = { whatsapp:a.whatsapp||"", line:a.line||"", phone:a.phone||"" }; });
  agentContacts[(ownerCreds&&ownerCreds.name)||"Annie"] = { whatsapp:(ownerCreds&&ownerCreds.whatsapp)||OWNER.whatsapp, line:(ownerCreds&&ownerCreds.line)||OWNER.lineUrl, phone:(ownerCreds&&ownerCreds.phone)||OWNER.phoneDisplay };

  if (dbLoading) return (
    <div style={{ minHeight:"100vh", display:"flex", alignItems:"center", justifyContent:"center", background:"#FDFAF6", flexDirection:"column", gap:16 }}>
      <div style={{ fontSize:40 }}>🏠</div>
      <div style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:22, color:"#1C1410" }}>Loading listings...</div>
      <div style={{ width:40, height:40, border:"3px solid #E5DDD3", borderTop:"3px solid #C9A96E", borderRadius:"50%", animation:"spin 1s linear infinite" }}/>
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
  if (screen === "login") return <AdminLogin agents={agents} pending={pending} onApply={handleApply} ownerCreds={ownerCreds} onLogin={(u) => { setCurrentUser(u); try{localStorage.setItem("bpf_user",JSON.stringify(u));}catch(_){} setScreen("admin"); localStorage.setItem("bpf_screen","admin"); }} />;

  return (
    <>
      {screen === "admin"
        ? <AdminDash props={props} onAdd={()=>setForm({})} onEdit={p=>setForm(p)} onDel={id=>setDelId(id)} onToggle={handleToggle}
            onLogout={()=>{ setScreen("site"); setAdminView(false); setCurrentUser(null); localStorage.removeItem("bpf_screen"); localStorage.removeItem("bpf_user"); }}
            onView={()=>{ setScreen("site"); setAdminView(true); }}
            onImportCSV={handleImportCSV} onImportSheets={handleImportCSV}
            onAIFill={handleAIFill} cityPhotos={cityPhotos} onCityPhoto={handleCityPhoto} visits={visits}
            currentUser={currentUser} agents={agents} onAgentsChange={handleAgents} pending={pending} onApprove={handleApprove} onReject={handleReject} onApproveListing={handleApproveListing} ownerCreds={ownerCreds} onSaveOwnerProfile={handleOwnerSelfUpdate} onAgentSelfUpdate={handleAgentSelfUpdate} onSetMaplink={handleSetMaplink}/>
        : <PublicSite props={props} isAdmin={adminView} cityPhotos={cityPhotos} agentContacts={agentContacts}
            onEditProp={p=>setForm(p)} onDelProp={id=>setDelId(id)}
            onGoAdmin={()=>setScreen(adminView?"admin":"login")}/>
      }
      {form !== null && <PropForm init={form&&form.id?form:null} onSave={handleSave} onClose={()=>setForm(null)} currentUser={currentUser} agents={agents}/>}
      {delId !== null && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.65)", zIndex:600, display:"flex", alignItems:"center", justifyContent:"center", padding:16 }}>
          <div style={{ background:"#fff", borderRadius:20, padding:"32px 26px", maxWidth:340, width:"100%", textAlign:"center", fontFamily:"'Outfit',sans-serif" }}>
            <div style={{ fontSize:42, marginBottom:12 }}>🗑️</div>
            <div style={{ fontFamily:"'Cormorant Garamond',serif", fontSize:22, fontWeight:700, color:"#1C1410", marginBottom:8 }}>Delete this listing?</div>
            <p style={{ color:"#7B6A5A", fontSize:13, marginBottom:22 }}>This cannot be undone.</p>
            <div style={{ display:"flex", gap:10 }}>
              <button onClick={()=>setDelId(null)} style={{ flex:1, background:"#F3EEE8", color:"#6B5E52", border:"none", padding:"11px", borderRadius:11, fontSize:13, fontWeight:600, cursor:"pointer" }}>Cancel</button>
              <button onClick={confirmDel} style={{ flex:1, background:"#EF4444", color:"#fff", border:"none", padding:"11px", borderRadius:11, fontSize:14, fontWeight:700, cursor:"pointer" }}>Delete</button>
            </div>
          </div>
        </div>
      )}
      {toast && (
        <div style={{ position:"fixed", bottom:22, right:22, background:"#1C1410", color:"#fff", padding:"11px 20px", borderRadius:11, fontSize:13, fontWeight:600, boxShadow:"0 6px 22px rgba(0,0,0,0.25)", zIndex:700, animation:"fadeUp 0.3s ease", border:"1px solid rgba(201,169,110,0.3)" }}>
          {toast}
        </div>
      )}
    </>
  );
}
